// Small AVIF versions of the images every page (or the home page) loads, plus
// a generated file with partner logo dimensions so <img> tags can reserve
// their space. The originals were far larger than they are ever shown:
// a 256px, 50 KB PNG for a 40-56px logo; partner PNGs up to 136 KB for a 64px
// strip; a 1030px phone screenshot shown at most 380px wide.
//
// Run after changing the logo, a partner logo, or the hero screenshot:
//   node scripts/build-brand-images.mjs
// Sources are never modified. Outputs are committed.
import sharp from "sharp";
import { readdirSync, statSync, writeFileSync } from "node:fs";

const kb = (p) => `${(statSync(p).size / 1024).toFixed(1)} KB`;

// 1. Logo: shown at 40px (navbar) and 56px (footer). 168px covers 3x.
const logoSrc = "public/assets/logo/new-unify-logo-256.png";
const logoOut = "public/assets/logo/new-unify-logo-168.avif";
await sharp(logoSrc).resize({ width: 168 }).avif({ quality: 62, effort: 9 }).toFile(logoOut);
console.log(`logo  ${kb(logoSrc)} -> ${kb(logoOut)}`);

// 2. Partner logos: shown at most 64px tall (home strip). 160px covers 2.5x.
const MAX_HEIGHT = 160;
const partnerDir = "public/assets/images/partners";
const sizes = {};
for (const file of readdirSync(partnerDir).filter((f) => f.endsWith(".png")).sort()) {
  const src = `${partnerDir}/${file}`;
  const out = src.replace(/\.png$/, ".avif");
  const { width, height } = await sharp(src)
    .resize({ height: MAX_HEIGHT, withoutEnlargement: true })
    .avif({ quality: 60, effort: 9 })
    .toFile(out);
  sizes[`/assets/images/partners/${file.replace(/\.png$/, ".avif")}`] = { width, height };
  console.log(`${file.padEnd(36)} ${kb(src).padStart(9)} -> ${kb(out).padStart(8)}  ${width}x${height}`);
}
writeFileSync(
  "src/lib/partner-logos.generated.ts",
  `// GENERATED by scripts/build-brand-images.mjs. Do not edit by hand.
// Intrinsic size of each partner logo, so <img> can carry width/height and the
// browser reserves the right space before the file arrives.
export const PARTNER_LOGO_SIZES: Record<string, { width: number; height: number }> = ${JSON.stringify(sizes, null, 2)};
`,
);

// 3. Hero phone screenshot: shown 181-380px wide. The 1030px original stays as
// the largest candidate.
const heroSrc = "public/assets/screenshots/learn-hero.avif";
for (const width of [380, 760]) {
  const out = `public/assets/screenshots/learn-hero-${width}.avif`;
  await sharp(heroSrc).resize({ width }).avif({ quality: 58, effort: 9 }).toFile(out);
  console.log(`hero ${width}w  ${kb(out)}  (original ${kb(heroSrc)})`);
}
